use vstd::prelude::*;
use vstd::vec::*;

verus! {

fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> (result: Vec<f32>)
    requires
        a.len() == mask.len(),  // mask must have same length as input array
        values.len() > 0,       // replacement array must be non-empty
    ensures
        result.len() == a.len(), // result has same length as input
        forall|i: int| 0 <= i && i < a.len() ==> 
            (mask[i] ==> result[i] == values[i % values.len()]) &&
            (!mask[i] ==> result[i] == a[i])
{
    // Ensure the replacement array is non-empty (as specified in the problem)
    assert!(!values.is_empty(), "Replacement array must be non-empty");
    
    // Create result vector with the same length as input array
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate through all elements
    let mut i: usize = 0;
    while i < a.len()
        invariant
            0 <= i && i <= a.len(),
            result.len() == i as int,
            forall|j: int| 0 <= j && j < i ==> 
                (mask[j] ==> result[j] == values[j % values.len()]) &&
                (!mask[j] ==> result[j] == a[j])
        decreases a.len() - i
    {
        if mask[i] {
            // Use modulo to get the index in values array
            let value_index = i % values.len();
            result.push(values[value_index]);
        } else {
            result.push(a[i]);
        }
        i += 1;
    }
    
    result
}

} // verus!